<script>const f=document.getElementById('booking-form'),q=document.getElementById('quote');async function quote(){const v=f.querySelector('[name=vehicle_id]:checked'),s=f.start_date.value,e=f.end_date.value;if(!v||!s||!e)return;const ids=[...f.querySelectorAll('[name="addon_ids[]"]:checked')].map(x=>x.value);q.innerHTML='<span class="animate-pulse">Menghitung harga…</span>';try{const r=await fetch(@json(route('booking.quote')),{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':f._token.value},body:JSON.stringify({vehicle_id:v.value,start_date:s,end_date:e,rental_type:f.rental_type.value,addon_ids:ids,promo_code:f.promo_code.value,pickup_location_id:f.pickup_location_id.value})});if(!r.ok)throw 0;const d=await r.json();q.innerHTML=`<div class="space-y-3"><div class="flex justify-between"><span>Durasi</span><b>${d.duration_days} hari</b></div><div class="flex justify-between"><span>Tarif efektif</span><b>Rp ${Number(d.effective_daily_rate).toLocaleString('id-ID')}</b></div><div class="flex justify-between"><span>Tambahan</span><b>Rp ${Number(d.addon_total).toLocaleString('id-ID')}</b></div><div class="flex justify-between text-emerald-700"><span>Diskon</span><b>- Rp ${Number(d.discount_amount).toLocaleString('id-ID')}</b></div><div class="flex justify-between border-t pt-4 text-lg text-slate-950"><strong>Total</strong><strong>Rp ${Number(d.total).toLocaleString('id-ID')}</strong></div></div>`}catch(e){q.innerHTML='<span class="text-red-700">Estimasi belum dapat dihitung. Periksa kendaraan dan tanggal.</span>'}}f.addEventListener('change',quote);window.quote=quote;</script></body></html>
